import java.util.*;
public class Solution{public static void main(String[]a){Scanner sc=new Scanner(System.in);String t=sc.next(),p=sc.next();int n=t.length(),m=p.length(),need[]=new int[256],win[]=new int[256],matched=0;for(char c:p.toCharArray())need[c]++;for(int i=0;i<m;i++){win[t.charAt(i)]++;if(win[t.charAt(i)]<=need[t.charAt(i)])matched++;}StringBuilder sb=new StringBuilder();if(matched==m)sb.append(0).append(" ");for(int i=m;i<n;i++){int in=t.charAt(i),out=t.charAt(i-m);win[in]++;if(win[in]<=need[in])matched++;win[out]--;if(win[out]<need[out])matched--;if(matched==m)sb.append(i-m+1).append(" ");}System.out.println(sb.toString().trim());}}
